const Database = require('better-sqlite3');
const db = new Database('/home/node/.n8n/wechat_monitor_paid_calls.sqlite');
db.exec(`CREATE TABLE IF NOT EXISTS summary_call_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    article_id TEXT NOT NULL,
    task_key TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('processing','success','failed','uncertain','skipped')),
    provider TEXT NOT NULL DEFAULT 'deepseek',
    model TEXT,
    prompt_version TEXT,
    run_id TEXT,
    feishu_record_id TEXT,
    request_hash TEXT,
    result_json TEXT,
    error_code TEXT,
    error_msg TEXT,
    started_at INTEGER NOT NULL,
    finished_at INTEGER,
    lock_until INTEGER NOT NULL,
    synced_to_feishu INTEGER NOT NULL DEFAULT 0
  );
  CREATE UNIQUE INDEX IF NOT EXISTS ux_summary_success_once ON summary_call_log(task_key) WHERE status = 'success';
  CREATE UNIQUE INDEX IF NOT EXISTS ux_summary_processing_once ON summary_call_log(task_key) WHERE status = 'processing';
  CREATE INDEX IF NOT EXISTS idx_summary_article ON summary_call_log(article_id, status);
  CREATE TABLE IF NOT EXISTS metrics_call_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    article_id TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('processing','success','failed','uncertain','skipped')),
    provider TEXT NOT NULL DEFAULT 'jizhile',
    run_id TEXT,
    feishu_record_id TEXT,
    url TEXT NOT NULL,
    request_hash TEXT,
    result_json TEXT,
    read_count INTEGER,
    like_count INTEGER,
    wow_count INTEGER,
    share_count INTEGER,
    collect_count INTEGER,
    comment_count INTEGER,
    error_code TEXT,
    error_msg TEXT,
    started_at INTEGER NOT NULL,
    finished_at INTEGER,
    lock_until INTEGER NOT NULL,
    synced_to_feishu INTEGER NOT NULL DEFAULT 0
  );
  CREATE UNIQUE INDEX IF NOT EXISTS ux_metrics_processing_once ON metrics_call_log(article_id) WHERE status = 'processing';
  CREATE INDEX IF NOT EXISTS idx_metrics_article_status_time ON metrics_call_log(article_id, status, started_at);
  CREATE INDEX IF NOT EXISTS idx_metrics_sync ON metrics_call_log(status, synced_to_feishu);`);
db.close();
const sd = $getWorkflowStaticData('global');
sd.stage2_run_stats = {
  total_records: 0, cache_hit_count: 0, claimed_count: 0,
  skipped_processing_count: 0, success_count: 0, failed_count: 0,
  uncertain_count: 0, run_started_at: Date.now()
};
return items;

function getField(fields, name) {
  const val = fields?.[name];
  if (val === null || val === undefined) return '';
  if (typeof val === 'string') return val;
  if (typeof val === 'number') return String(val);
  if (Array.isArray(val)) {
    return val.map(seg => {
      if (typeof seg === 'string') return seg;
      if (seg?.text) return String(seg.text);
      return '';
    }).join('');
  }
  if (typeof val === 'object') {
    if (val.text !== undefined) return String(val.text);
    if (val.value !== undefined) return String(val.value);
    return JSON.stringify(val);
  }
  return String(val);
}

const resp = items[0]?.json || {};
const records = resp.data?.items || resp.items || resp.records || resp.data?.records || [];
if (!records.length) return [];
return records
  .map(r => ({
    json: {
      record_id: r.record_id || r.id || '',
      article_id: getField(r.fields, 'article_id'),
      markdown: getField(r.fields, 'markdown'),
    }
  }))
  .filter(item => item.json.article_id && item.json.markdown);

const now = Date.now();
const item = items[0].json;
const article_id = item.article_id || '';
if (!article_id) {
  throw new Error('article_id 为空，拒绝生成摘要，避免 task_key 冲突');
}
const prompt_version = item.prompt_version;
const model = item.model;
const task_key = `${prompt_version}:${model}:${article_id}`;
const run_id = `s2-${now}-${Math.random().toString(36).slice(2, 8)}`;
return [{
  json: {
    ...item,
    task_key,
    run_id,
    started_at: now,
    lock_until: now + 30 * 60 * 1000,
  }
}];

const Database = require('better-sqlite3');
const db = new Database('/home/node/.n8n/wechat_monitor_paid_calls.sqlite');
const item = items[0].json;
const row = db.prepare(`SELECT id, result_json FROM summary_call_log WHERE task_key = ? AND status = 'success' LIMIT 1`).get(item.task_key);
db.close();
let check_result = null;
let cached_summary_v2 = '';
let cached_article_type = '', cached_type_reason = '', cached_policy_entity = '[]', cached_topic_tags_v2 = '[]', cached_target_company_type = '[]', cached_key_facts = '{}';
if (row) {
  let parsed = {};
  try { parsed = JSON.parse(row.result_json || '{}'); } catch(e) {}
  if (parsed.summary_v2 && String(parsed.summary_v2).trim()) {
    check_result = 'ALREADY_SUCCESS';
    cached_summary_v2 = String(parsed.summary_v2).trim();
    cached_article_type = parsed.article_type || '';
    cached_type_reason = parsed.type_reason || '';
    cached_policy_entity = typeof parsed.policy_entity === 'string' ? parsed.policy_entity : JSON.stringify(parsed.policy_entity || []);
    cached_topic_tags_v2 = typeof parsed.topic_tags_v2 === 'string' ? parsed.topic_tags_v2 : JSON.stringify(parsed.topic_tags_v2 || []);
    cached_target_company_type = typeof parsed.target_company_type === 'string' ? parsed.target_company_type : JSON.stringify(parsed.target_company_type || []);
    cached_key_facts = typeof parsed.key_facts === 'string' ? parsed.key_facts : JSON.stringify(parsed.key_facts || {});
  } else {
    check_result = 'SUCCESS_CACHE_INVALID';
  }
}
return [{ json: { ...item, check_result, cached_summary_v2, cached_article_type, cached_type_reason, cached_policy_entity, cached_topic_tags_v2, cached_target_company_type, cached_key_facts } }];

const Database = require('better-sqlite3');
const db = new Database('/home/node/.n8n/wechat_monitor_paid_calls.sqlite');
const item = items[0].json;
const { task_key, article_id, record_id, run_id, lock_until, started_at, prompt_version, model } = item;
const now = Date.now();
let lock_result = 'CLAIMED';
const txn = db.transaction(() => {
  const sr = db.prepare(`SELECT id FROM summary_call_log WHERE task_key = ? AND status = 'success' LIMIT 1`).get(task_key);
  if (sr) { lock_result = 'ALREADY_SUCCESS'; return; }
  const pr = db.prepare(`SELECT id, lock_until as lu FROM summary_call_log WHERE task_key = ? AND status = 'processing' LIMIT 1`).get(task_key);
  if (pr) {
    if (pr.lu > now) { lock_result = 'ALREADY_PROCESSING'; return; }
    db.prepare(`UPDATE summary_call_log SET status = 'uncertain' WHERE id = ?`).run(pr.id);
    lock_result = 'LOCK_EXPIRED_REVIEW'; return;
  }
  try {
    db.prepare(`INSERT INTO summary_call_log (article_id,task_key,status,provider,model,prompt_version,run_id,feishu_record_id,started_at,lock_until,synced_to_feishu) VALUES (?,?,'processing','deepseek',?,?,?,?,?,?,0)`).run(article_id,task_key,model,prompt_version,run_id,record_id,started_at,lock_until);
  } catch (e) {
    if (e.code === 'SQLITE_CONSTRAINT_UNIQUE' || String(e.message).includes('UNIQUE')) {
      lock_result = 'ALREADY_PROCESSING';
    } else {
      throw e;
    }
  }
});
txn();
db.close();
return [{ json: { ...item, lock_result } }];

const item = items[0].json;
const markdown = item.markdown || '';
const PROMPT = item.summary_prompt_template || '';
if (!PROMPT.trim()) throw new Error('summary_prompt_template 为空');
if (!markdown.trim()) throw new Error('markdown 为空');
return [{
  json: {
    ...item,
    summary_prompt: PROMPT + '\n\n' + markdown
  }
}];

const Database = require('better-sqlite3');
const db = new Database('/home/node/.n8n/wechat_monitor_paid_calls.sqlite');
const item = items[0].json;
const { task_key, run_id, summary_v2, article_type, type_reason, policy_entity, topic_tags_v2, target_company_type, key_facts, finished_at } = item;
function safeParse(v, fallback) { try { return typeof v === 'string' ? JSON.parse(v) : v; } catch(e) { return fallback; } }
const result_json = JSON.stringify({ summary_v2, article_type, type_reason, policy_entity: safeParse(policy_entity, []), topic_tags_v2: safeParse(topic_tags_v2, []), target_company_type: safeParse(target_company_type, []), key_facts: safeParse(key_facts, {}) });
const res = db.prepare(`UPDATE summary_call_log SET status='success', result_json=?, finished_at=? WHERE task_key=? AND status='processing' AND run_id=?`).run(result_json, finished_at, task_key, run_id);
if (res.changes !== 1) {
  const existing = db.prepare(`SELECT id FROM summary_call_log WHERE task_key=? AND status='success' LIMIT 1`).get(task_key);
  if (!existing) {
    db.close();
    throw new Error(`SQLite success update failed (changes=${res.changes}). task_key=${task_key}, run_id=${run_id}. 人工检查 summary_call_log。`);
  }
}
db.close();
const sd = $getWorkflowStaticData('global');
if (sd.stage2_run_stats) {
  sd.stage2_run_stats.success_count++;
  sd.stage2_run_stats.claimed_count++;
  sd.stage2_run_stats.total_records++;
}
return [{ json: { ...item, result_json } }];

const Database = require('better-sqlite3');
const db = new Database('/home/node/.n8n/wechat_monitor_paid_calls.sqlite');

let task_key = items[0].json?.task_key || '';

if (!task_key) {
  try {
    const arr = $('Set Summary From Cache').all();
    task_key = arr[arr.length - 1]?.json?.task_key || '';
  } catch(e) {}
}

if (!task_key) {
  try {
    const arr = $('Write SQLite Success').all();
    task_key = arr[arr.length - 1]?.json?.task_key || '';
  } catch(e) {}
}

if (!task_key) {
  try {
    const arr = $('Check SQLite Success').all();
    task_key = arr[arr.length - 1]?.json?.task_key || '';
  } catch(e) {}
}

if (!task_key) {
  db.close();
  throw new Error('task_key 为空，无法标记 synced_to_feishu');
}

db.prepare(`UPDATE summary_call_log SET synced_to_feishu=1 WHERE task_key=? AND status='success'`).run(task_key);
db.close();
return items;

const dsResp = items[0].json;
let origItem;
try { origItem = $('Prepare DeepSeek Payload').first().json; } catch(e) { origItem = dsResp; }
const now = Date.now();
let deepseek_status, summary_v2, article_type, type_reason, policy_entity, topic_tags_v2, target_company_type, key_facts, error_code, error_msg;
let raw_content, parse_status, finish_reason, usage_total_tokens, raw_head, raw_tail;
if (dsResp.error) {
  const errObj = dsResp.error;
  const code = errObj?.code || errObj?.type || errObj?.status || 'API_ERROR';
  const msg = errObj?.message || String(errObj || '');
  const httpStatus = typeof errObj?.status === 'number' ? errObj.status : 0;
  deepseek_status = (httpStatus >= 400 && httpStatus < 500) ? 'failed' : 'uncertain';
  error_code = String(code).slice(0, 64);
  error_msg = String(msg).slice(0, 500);
  summary_v2 = '';
} else {
  const content = dsResp.choices?.[0]?.message?.content || dsResp.message?.content || dsResp.text || dsResp.output || '';
  finish_reason = dsResp.choices?.[0]?.finish_reason || '';
  usage_total_tokens = dsResp.usage?.total_tokens || 0;
  const raw_content_str = String(content);
  raw_head = raw_content_str.slice(0, 500);
  raw_tail = raw_content_str.length > 500 ? raw_content_str.slice(-500) : '';
  if (String(content).trim()) {
    let parsed = null;
    let parse_exception = false;
    try {
      const raw = String(content).trim();
      const jsonMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
      parsed = JSON.parse(jsonMatch ? jsonMatch[1].trim() : raw);
    } catch(e) { parsed = null; parse_exception = true; }
    if (!parsed) {
      try {
        const raw = String(content);
        const start = raw.indexOf('{');
        const end = raw.lastIndexOf('}');
        if (start !== -1 && end > start) parsed = JSON.parse(raw.slice(start, end + 1));
        if (parsed) parse_exception = false;
      } catch(e) { parsed = null; }
    }
    if (parsed && parsed.summary_v2) {
      deepseek_status = 'success';
      summary_v2 = String(parsed.summary_v2 || '').trim();
      article_type = String(parsed.article_type || '');
      type_reason = String(parsed.type_reason || '');
      policy_entity = JSON.stringify(Array.isArray(parsed.policy_entity) ? parsed.policy_entity : []);
      topic_tags_v2 = JSON.stringify(Array.isArray(parsed.topic_tags_v2) ? parsed.topic_tags_v2 : []);
      target_company_type = JSON.stringify(Array.isArray(parsed.target_company_type) ? parsed.target_company_type : []);
      key_facts = JSON.stringify(parsed.key_facts || {});
      error_code = null;
      error_msg = null;
    } else {
      deepseek_status = 'uncertain';
      raw_content = raw_content_str.slice(0, 2000);
      parse_status = 'json_parse_failed';
      if (parse_exception || parsed === null) {
        error_code = 'JSON_INCOMPLETE';
        error_msg = '返回内容 JSON 解析失败，可能因 token 截断导致 JSON 不完整';
      } else {
        error_code = 'SCHEMA_MISSING_FIELD';
        error_msg = '返回内容 JSON 解析成功但缺少 summary_v2 字段';
      }
      summary_v2 = '';
    }
  } else {
    deepseek_status = 'uncertain';
    error_code = 'EMPTY_RESPONSE';
    error_msg = '摘要内容为空';
    summary_v2 = '';
  }
}
return [{ json: { ...origItem, deepseek_status, summary_v2, article_type, type_reason, policy_entity, topic_tags_v2, target_company_type, key_facts, error_code, error_msg, raw_content, parse_status, finish_reason, usage_total_tokens, raw_head, raw_tail, finished_at: now } }];

const Database = require('better-sqlite3');
const db = new Database('/home/node/.n8n/wechat_monitor_paid_calls.sqlite');
const item = items[0].json;
const { task_key, run_id, deepseek_status, error_code, error_msg, finished_at, finish_reason, usage_total_tokens, raw_head, raw_content } = item;
const diag_prefix = `finish=${finish_reason || ''}|tokens=${usage_total_tokens || 0}|head=${(raw_head || '').slice(0, 200)}|`;
const enriched_error_msg = (diag_prefix + (error_msg || '')).slice(0, 500);
const result_json_to_store = raw_content ? String(raw_content).slice(0, 2000) : null;
db.prepare(`UPDATE summary_call_log SET status=?, error_code=?, error_msg=?, result_json=?, finished_at=? WHERE task_key=? AND status='processing' AND run_id=?`).run(deepseek_status, error_code, enriched_error_msg, result_json_to_store, finished_at, task_key, run_id);
db.close();
const sd = $getWorkflowStaticData('global');
if (sd.stage2_run_stats) {
  if (deepseek_status === 'failed') sd.stage2_run_stats.failed_count++;
  else sd.stage2_run_stats.uncertain_count++;
  sd.stage2_run_stats.claimed_count++;
  sd.stage2_run_stats.total_records++;
}
return items;

const sd = $getWorkflowStaticData('global');
if (sd.stage2_run_stats) {
  sd.stage2_run_stats.skipped_processing_count++;
  sd.stage2_run_stats.total_records++;
}
return items;

const sd = $getWorkflowStaticData('global');
const stats = { ...(sd.stage2_run_stats || {}) };
delete sd.stage2_run_stats;
const duration_ms = stats.run_started_at ? (Date.now() - stats.run_started_at) : null;
return [{ json: {
  workflow: 'W2R V2 Stage2 - 摘要 Worker',
  total_records: stats.total_records || 0,
  cache_hit_count: stats.cache_hit_count || 0,
  claimed_count: stats.claimed_count || 0,
  skipped_processing_count: stats.skipped_processing_count || 0,
  success_count: stats.success_count || 0,
  failed_count: stats.failed_count || 0,
  uncertain_count: stats.uncertain_count || 0,
  duration_ms,
  finished_at: new Date().toISOString()
} }];

const item = items[0].json;
const cached_summary_v2 = String(item.cached_summary_v2 || '').trim();
if (!cached_summary_v2) {
  throw new Error('cached_summary_v2 为空，拒绝写入飞书');
}
const sd = $getWorkflowStaticData('global');
if (sd.stage2_run_stats) {
  sd.stage2_run_stats.cache_hit_count++;
  sd.stage2_run_stats.total_records++;
}
return [{
  json: {
    ...item,
    summary_v2: cached_summary_v2,
    article_type: item.cached_article_type || '',
    type_reason: item.cached_type_reason || '',
    policy_entity: item.cached_policy_entity || '[]',
    topic_tags_v2: item.cached_topic_tags_v2 || '[]',
    target_company_type: item.cached_target_company_type || '[]',
    key_facts: item.cached_key_facts || '{}',
    summary_source: 'sqlite_cache'
  }
}];
